// Documento "datos básicos" de Ibercaja (sustituye Zapier "Ibercaja Datos de la operación nuevo documento"
// + Apps Script generarPlantillasIbercaja). UNA fila y UN documento por Opportunity ID:
//  - si la fila ya tiene enlace (col R) o ya existe el documento en la carpeta → se reutiliza
//  - si no → se copia la plantilla, se rellena y se guarda el enlace en R
const input = $('Entrada').first().json;
const deal = input.dealGeneral || {};
const rv = (v) => (v && typeof v === 'object' && 'value' in v) ? v.value : (v ?? '');
const pick = (key) => rv(deal[key]);
const num = (v) => { const n = Number(String(v ?? '').replace(/[^0-9.,-]/g, '').replace(',', '.')); return Number.isFinite(n) && String(v ?? '') !== '' ? n : ''; };
const provinciaMap = {
  '2553': 'Albacete', '2554': 'Alicante/Alacant', '2555': 'Almería',
  '2556': 'Araba/Álava', '2557': 'Asturias', '2558': 'Ávila',
  '2559': 'Badajoz', '2560': 'Balears, Illes', '2561': 'Barcelona',
  '2562': 'Bizkaia', '2563': 'Burgos', '2564': 'Cáceres',
  '2565': 'Cádiz', '2566': 'Cantabria', '2567': 'Castellón/Castelló',
  '2568': 'Ciudad Real', '2569': 'Córdoba', '2570': 'Coruña, A',
  '2571': 'Cuenca', '2572': 'Gipuzkoa', '2573': 'Girona',
  '2574': 'Granada', '2575': 'Guadalajara', '2576': 'Huelva',
  '2577': 'Huesca', '2578': 'Jaén', '2579': 'León',
  '2580': 'Lleida', '2581': 'Lugo', '2582': 'Madrid',
  '2583': 'Málaga', '2584': 'Murcia', '2585': 'Navarra',
  '2586': 'Ourense', '2587': 'Palencia', '2588': 'Palmas, Las',
  '2589': 'Pontevedra', '2590': 'Rioja, La', '2591': 'Salamanca',
  '2592': 'Santa Cruz de Tenerife', '2593': 'Segovia', '2594': 'Sevilla',
  '2595': 'Soria', '2596': 'Tarragona', '2597': 'Teruel',
  '2598': 'Toledo', '2599': 'Valencia/València', '2600': 'Valladolid',
  '2601': 'Zamora', '2602': 'Zaragoza', '2603': 'Ceuta',
  '2604': 'Melilla', '2605': 'Canarias', '3052': 'Vitoria',
  '3053': 'Oviedo', '3113': 'TBC'
};
const tipoCompraMap = {
  '2547': 'Primera residencia', '2548': 'Segunda residencia',
  '2549': 'Inversión', '2550': 'Cambio de hipoteca',
  '2551': 'Extinción de condominio', '2552': 'Autopromoción'
};


const oppId = String(input.opportunityId || deal.id || '').trim();
if (!/^\d+$/.test(oppId)) throw new Error('Falta Opportunity ID');
const nombre = String(input.nombreCliente || deal.person_name || rv(deal.person_id?.name) || '').trim();

const provincia = provinciaMap[String(pick('15edcbc34620af8067c2413c2d9793b2a6bba3ba'))] || '';
const tipoOperacion = tipoCompraMap[String(pick('bc2fb38a576f000bd311e49d4da2dd20dbf9439b'))] || '';
const titular2 = pick('209a0da7966a29bf05e96b6a124536222e0318dd');
const dni2 = pick('c83f49f1e2fd08f55a16b159dd88802d2b5baa04');
const importeHipoteca = num(pick('b80d8ee37cc14ecdd7d8a640a57d6bd85308d5b9'));
const importeVivienda = num(pick('184fc13001dbca74b20c77f0fcfdec161b5cb492'));
const ltc = importeHipoteca && importeVivienda ? Math.round(importeHipoteca / importeVivienda * 10000) / 100 : '';
const plazo = num(pick('718ded557b843ad6ec94558a1da186ca063b11ee'));
const dti = num(pick('e1d74951df7afc36b15725af21f21f8d2f89cff6'));

// Oficina por provincia ("Lista Actualizada": A provincia, C código, G territorial)
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const keys = (s) => [norm(s), norm(String(s).split('/')[0]), norm(String(s).split('/')[1] || '')].filter(Boolean);
const oficinas = ($('Leer oficinas').first().json.values || []).slice(1);
const wanted = keys(provincia);
const of = oficinas.find(r => keys(r[0]).some(k => wanted.includes(k)));
const oficina = of ? String(of[2] || '').trim() : '';   // código de oficina (col C), como el Zapier
const territorial = of ? String(of[6] || '').trim() : '';

// Fila: la ÚLTIMA con este Opportunity ID en col A (hay duplicados históricos del Zapier) o una nueva al final
const rows = $('Leer Excel').first().json.values || [];
let rowIdx = -1;
for (let i = rows.length - 1; i > 0; i--) if (String(rows[i]?.[0] ?? '').trim() === oppId) { rowIdx = i; break; }
const existingRow = rowIdx > 0;
const linkFila = existingRow ? String(rows[rowIdx][17] || '').trim() : '';
if (!existingRow) rowIdx = rows.length;
const r = rowIdx + 1;

// Documento ya creado en la carpeta (por el script antiguo o por este flujo)
const files = ($('Buscar documento').first().json.files || []).filter(f => String(f.name || '').startsWith(oppId + '-'));
const linkDrive = files.length ? `https://docs.google.com/spreadsheets/d/${files[0].id}/edit?usp=drivesdk` : '';
const link = linkFila || linkDrive;

// Col B "Oficina" = bank mail del deal bancario; si no tiene, código de oficina por provincia
const bankMail = String(input.bankMail || rv((input.bankDeal || {})['498dd83b5c5e1f1181c232131933717ceadfda34']) || '').trim();
const colOficina = bankMail.includes('@') ? bankMail : (oficina || (provincia ? `PROVINCIA NO ENCONTRADA: ${provincia}` : 'SIN PROVINCIA'));
const fila = [oppId, colOficina, territorial,
  nombre, pick('60228dc43313b931378ec9bb3f21f7ad7f5a144c'), provincia, titular2, dni2, titular2 ? provincia : '',
  tipoOperacion, importeHipoteca, importeVivienda, ltc, '', plazo, '', provincia];

// Celdas de la plantilla (mismas que generarPlantillasIbercaja)
const celdas = [['B3', fila[1]], ['B4', territorial], ['B5', nombre], ['B6', fila[4]], ['B7', provincia],
  ['B8', titular2], ['B9', dni2], ['B10', fila[8]], ['B11', tipoOperacion], ['B12', importeHipoteca],
  ['B13', importeVivienda], ['B14', ltc], ['B15', dti], ['B16', plazo], ['B18', provincia]]
  .map(([range, v]) => ({ range, values: [[v ?? '']] }));

return [{ json: {
  opportunityId: oppId, nombre, docName: `${oppId}-${nombre}`, row: r, existingRow, link,
  reused: link ? (linkFila ? 'fila' : 'drive') : null, needCreate: !link && !input.dryRun, dryRun: !!input.dryRun,
  provincia, oficinaEncontrada: !!of, fila, dti,
  templateBody: { valueInputOption: 'USER_ENTERED', data: celdas },
} }];

// Añade el enlace del documento (reutilizado o recién creado) y prepara la escritura de la fila
const p = $('Preparar fila').first().json;
let link = p.link, created = false;
if ($('Copiar plantilla').isExecuted) {
  const id = $('Copiar plantilla').first().json.id;
  if (id) { link = `https://docs.google.com/spreadsheets/d/${id}/edit?usp=drivesdk`; created = true; }
}
const r = p.row;
const data = [
  { range: `Sheet2!A${r}:Q${r}`, values: [p.fila] },
  { range: `Sheet2!S${r}`, values: [[p.dti]] },
];
if (link) data.push({ range: `Sheet2!R${r}`, values: [[link]] });
const docId = ((link || '').match(/\/d\/([a-zA-Z0-9_-]+)/) || [])[1] || '';
// Documento reutilizado: se vuelve a rellenar y renombrar con los datos actuales (antes se quedaba con los del 1er intento)
const refresh = !created && !!docId && !p.dryRun;
return [{ json: { ...p, link, created, docId, refresh, body: { valueInputOption: 'USER_ENTERED', data } } }];

const j = $('Enlace y fila').first().json;
return [{ json: { ok: !!j.link, opportunityId: j.opportunityId, docName: j.docName, link: j.link, created: j.created,
  reused: j.reused, refreshed: $('Renombrar documento').isExecuted, row: j.row, existingRow: j.existingRow, dryRun: j.dryRun, provincia: j.provincia, oficinaEncontrada: j.oficinaEncontrada } }];
